Facing this as well in Next.js 16.2.10 (both in dev and prod). Here's a workaround:

`src/pages/_document.page/background-tab-hydration-fix.tsx`

```tsx
import type * as React from "react";

const backgroundTabHydrationFixScript = `(function () {
  var patch = function (requestName, cancelName, makeDeadline) {
    var request = window[requestName];
    if (typeof request !== "function") return;
    request = request.bind(window);
    var cancel = typeof window[cancelName] === "function" ? window[cancelName].bind(window) : null;
    var fallbackIds = new Set();
    window[requestName] = function (callback) {
      if (document.visibilityState !== "hidden") return request(callback);
      var id = window.setTimeout(function () {
        fallbackIds.delete(id);
        callback(makeDeadline());
      }, 0);
      fallbackIds.add(id);
      return id;
    };
    window[cancelName] = function (id) {
      if (fallbackIds.delete(id)) return window.clearTimeout(id);
      if (cancel) cancel(id);
    };
  };
  patch("requestAnimationFrame", "cancelAnimationFrame", function () {
    return performance.now();
  });
  patch("requestIdleCallback", "cancelIdleCallback", function () {
    return { didTimeout: true, timeRemaining: function () { return 0; } };
  });
})();`;

/**
 * Renders a pre-hydration shim as an inline `<script>`, so it runs before the Next.js client
 * bundle (and thus before hydration is scheduled). Must be placed inside `<Head>` in `_document`.
 *
 * A browser tab that has never been foregrounded never fires `requestAnimationFrame` (and often
 * not `requestIdleCallback` either), even though promises, timers and MessageChannel keep
 * running. Next.js gates hydration on exactly one such callback: its Turbopack production client
 * entry (`next/dist/client/next-turbopack.js`) wires the dev FOUC helper in as
 * `hydrate({ beforeRender: displayContent })`, `hydrate()` awaits it before rendering, and
 * `displayContent` only resolves from inside a `requestAnimationFrame`. So in a background tab
 * (e.g. one an agent opens) React never hydrates and the app is stuck on its loading shutter
 * ("Signing you in...") until the tab is focused. This affects production builds, not just the
 * dev server - and the shim is a no-op for the FOUC cleanup it gates, as production emits no
 * `data-next-hide-fouc` elements.
 *
 * While the document is hidden there is no paint to wait for, so routing rAF/rIC callbacks
 * through a macrotask lets hydration (and any other rAF/rIC-gated work) proceed. When the tab is
 * visible, native scheduling is used unchanged, so there is no effect on foreground rendering.
 *
 * Remove once fixed upstream - Next.js already applies the same `setTimeout` fallback inside
 * iframes, just not for hidden tabs.
 *
 * @see https://github.com/vercel/next.js/issues/90684 - Turbopack Pages Router hydration delayed
 * when tab opened in background (open; our exact scenario)
 */
export const BackgroundTabHydrationFix: React.FunctionComponent = () => {
  return (
    // eslint-disable-next-line @eslint-react/dom-no-dangerously-set-innerhtml -- pre-hydration shim must run before the Next.js client bundle
    <script dangerouslySetInnerHTML={{ __html: backgroundTabHydrationFixScript }} />
  );
};
```

